import{_ as i,o as t,c as l,ae as e}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"템플릿 내역 가져오기(CSV)","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/01-template-bill-import-guide.md","filePath":"v1/ko/guide/01-template-bill-import-guide.md"}'),r={name:"v1/ko/guide/01-template-bill-import-guide.md"};function s(o,a,d,h,n,c){return t(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="템플릿-내역-가져오기-csv" tabindex="-1">템플릿 내역 가져오기(CSV) <a class="header-anchor" href="#템플릿-내역-가져오기-csv" aria-label="Permalink to &quot;템플릿 내역 가져오기(CSV)&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>코알라 가계부는 외부 파일에서 거래 내역을 가져와 과거 기록을 빠르게 옮길 수 있습니다. 현재 다음 방식의 가져오기를 지원합니다.</p><ul><li><strong>템플릿 파일 가져오기</strong>: 표준 형식의 CSV 파일 가져오기</li><li><strong>WeChat 가져오기</strong>: WeChat에서 내보낸 거래 내역 파일 가져오기</li><li><strong>Alipay 가져오기</strong>: Alipay에서 내보낸 거래 내역 파일 가져오기</li><li><strong>Pixiu 가져오기</strong>: Pixiu에서 내보낸 CSV 파일 가져오기</li><li><strong>iCost 가져오기</strong>: iCost에서 내보낸 Excel 파일 가져오기</li></ul><hr><h2 id="📁-지원-파일-형식" tabindex="-1">📁 지원 파일 형식 <a class="header-anchor" href="#📁-지원-파일-형식" aria-label="Permalink to &quot;📁 지원 파일 형식&quot;">​</a></h2><ul><li><strong>CSV</strong> (<code>.csv</code>): Alipay, Pixiu, 템플릿</li><li><strong>Excel</strong> (<code>.xlsx</code>, <code>.xls</code>): WeChat, iCost</li></ul><hr><h2 id="🚀-빠른-시작" tabindex="-1">🚀 빠른 시작 <a class="header-anchor" href="#🚀-빠른-시작" aria-label="Permalink to &quot;🚀 빠른 시작&quot;">​</a></h2><h3 id="_1단계-가져오기-화면-열기" tabindex="-1">1단계: 가져오기 화면 열기 <a class="header-anchor" href="#_1단계-가져오기-화면-열기" aria-label="Permalink to &quot;1단계: 가져오기 화면 열기&quot;">​</a></h3><ol><li>코알라 가계부 앱을 엽니다</li><li>하단의 <strong>설정</strong>을 탭합니다</li><li>설정 화면에서 <strong>내역 가져오기</strong>를 찾습니다</li><li>내역 가져오기 화면으로 들어갑니다</li></ol><h3 id="_2단계-가져오기-소스-선택" tabindex="-1">2단계: 가져오기 소스 선택 <a class="header-anchor" href="#_2단계-가져오기-소스-선택" aria-label="Permalink to &quot;2단계: 가져오기 소스 선택&quot;">​</a></h3><p>가져오기 화면에서 내역의 출처를 선택합니다.</p><ul><li><strong>템플릿 파일</strong></li><li><strong>WeChat</strong></li><li><strong>Alipay</strong></li><li><strong>Pixiu</strong></li><li><strong>iCost</strong></li></ul><blockquote><p>⚠️ <strong>중요</strong>: 소스를 잘못 선택하면 파싱에 실패하거나 항목이 어긋나게 읽힐 수 있습니다.</p></blockquote><h3 id="_3단계-파일-선택" tabindex="-1">3단계: 파일 선택 <a class="header-anchor" href="#_3단계-파일-선택" aria-label="Permalink to &quot;3단계: 파일 선택&quot;">​</a></h3><ol><li><strong>파일 경로</strong>를 탭합니다</li><li>파일 선택기에서 가져올 파일을 선택합니다</li><li>선택된 파일명이 표시되는지 확인합니다</li></ol><blockquote><p>📝 <strong>참고</strong>:</p><ul><li>파일은 기기 로컬에 저장되어 있어야 합니다(파일 관리자에서 접근 가능한 위치)</li><li>파일 형식(CSV/Excel)이 올바른지 확인하세요</li><li>파일이 손상된 경우 다시 내보내서 시도해 주세요</li></ul></blockquote><h3 id="_4단계-장부-연결" tabindex="-1">4단계: 장부 연결 <a class="header-anchor" href="#_4단계-장부-연결" aria-label="Permalink to &quot;4단계: 장부 연결&quot;">​</a></h3><ol><li><strong>장부 연결</strong>을 탭합니다</li><li>어느 장부로 가져올지 선택합니다</li></ol><blockquote><p>💡 팁: 장부가 1개만 있는 경우 기본 장부로 자동 연결될 수 있습니다.</p></blockquote><h3 id="_5단계-파싱" tabindex="-1">5단계: 파싱 <a class="header-anchor" href="#_5단계-파싱" aria-label="Permalink to &quot;5단계: 파싱&quot;">​</a></h3><ol><li>우측 상단의 <strong>파싱</strong>을 탭합니다</li><li>파싱이 완료되면 미리보기 화면으로 이동합니다</li></ol><h3 id="_6단계-미리보기-및-수정" tabindex="-1">6단계: 미리보기 및 수정 <a class="header-anchor" href="#_6단계-미리보기-및-수정" aria-label="Permalink to &quot;6단계: 미리보기 및 수정&quot;">​</a></h3><p>미리보기 화면에서:</p><ul><li>날짜별로 묶인 내역을 확인할 수 있습니다</li><li>단건 편집(카테고리, 금액, 시간, 계정, 태그, 메모 등)이 가능합니다</li><li>잘못된 항목은 길게 눌러 삭제할 수 있습니다</li><li>유효하지 않은 항목은 일괄로 건너뛸 수 있습니다</li></ul><h3 id="_7단계-가져오기-실행" tabindex="-1">7단계: 가져오기 실행 <a class="header-anchor" href="#_7단계-가져오기-실행" aria-label="Permalink to &quot;7단계: 가져오기 실행&quot;">​</a></h3><ol><li>내용이 맞는지 확인한 뒤 <strong>가져오기</strong>를 탭합니다</li><li>완료될 때까지 기다립니다</li></ol><hr><h2 id="📝-템플릿-csv-형식-안내" tabindex="-1">📝 템플릿 CSV 형식 안내 <a class="header-anchor" href="#📝-템플릿-csv-형식-안내" aria-label="Permalink to &quot;📝 템플릿 CSV 형식 안내&quot;">​</a></h2><p>템플릿 파일로 가져오려면 아래 형식으로 CSV를 준비해 주세요.</p><h3 id="csv-요구사항" tabindex="-1">CSV 요구사항 <a class="header-anchor" href="#csv-요구사항" aria-label="Permalink to &quot;CSV 요구사항&quot;">​</a></h3><ol><li><strong>인코딩</strong>: UTF-8 또는 GBK</li><li><strong>구분자</strong>: 쉼표 <code>,</code></li><li><strong>헤더</strong>: 1행에 헤더 필수</li></ol><h3 id="표준-예시" tabindex="-1">표준 예시 <a class="header-anchor" href="#표준-예시" aria-label="Permalink to &quot;표준 예시&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">类型,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">金额,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">分类,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">账户,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">备注,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">标签</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">支出,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">100.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">餐饮,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">现金,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">午餐,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">工作餐</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-02,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">收入,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5000.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">工资,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">银行卡,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">月薪,</span></span></code></pre></div><h3 id="필드-설명" tabindex="-1">필드 설명 <a class="header-anchor" href="#필드-설명" aria-label="Permalink to &quot;필드 설명&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th><th>필수</th><th>예시</th></tr></thead><tbody><tr><td>거래 날짜</td><td>날짜 형식: <code>yyyy/MM/dd</code></td><td>✅</td><td>2026/01/01</td></tr><tr><td>수입/지출</td><td>지출 또는 수입</td><td>✅</td><td>支出 / 收入</td></tr><tr><td>대분류</td><td>1단계 카테고리명</td><td>✅</td><td>伙食</td></tr><tr><td>소분류</td><td>2단계 카테고리명</td><td>✅</td><td>早餐</td></tr><tr><td>유입 금액</td><td>수입일 때 사용하는 금액</td><td>✅</td><td>100.00</td></tr><tr><td>유출 금액</td><td>지출일 때 사용하는 금액</td><td>✅</td><td>15</td></tr><tr><td>계정</td><td>계정명(가능하면 코알라 가계부에 이미 존재하는 계정명)</td><td>✅</td><td>默认账户</td></tr><tr><td>메모</td><td>메모</td><td>❌</td><td>午餐</td></tr><tr><td>태그</td><td>태그명(복수는 쉼표로 구분)</td><td>❌</td><td>工作餐,聚餐</td></tr></tbody></table><h3 id="템플릿-다운로드" tabindex="-1">템플릿 다운로드 <a class="header-anchor" href="#템플릿-다운로드" aria-label="Permalink to &quot;템플릿 다운로드&quot;">​</a></h3><ol><li>가져오기 화면에서 <strong>템플릿 다운로드</strong>를 탭합니다</li><li>예시 CSV 파일이 다운로드됩니다</li><li>해당 형식을 참고해 데이터를 준비해 주세요</li></ol><hr><h2 id="⚠️-유의사항" tabindex="-1">⚠️ 유의사항 <a class="header-anchor" href="#⚠️-유의사항" aria-label="Permalink to &quot;⚠️ 유의사항&quot;">​</a></h2><h3 id="_1-데이터-형식" tabindex="-1">1. 데이터 형식 <a class="header-anchor" href="#_1-데이터-형식" aria-label="Permalink to &quot;1. 데이터 형식&quot;">​</a></h3><ul><li><strong>날짜</strong>: <code>YYYY/MM/DD</code> (예: <code>2026/01/01</code>)</li><li><strong>금액</strong>: 숫자 형식(소수점 가능, 예: <code>100.00</code>)</li><li><strong>수입/지출</strong>: <code>支出</code> 또는 <code>收入</code></li><li><strong>카테고리/계정</strong>: 코알라 가계부에 없는 경우 가져오기 중 자동 생성될 수 있습니다</li></ul><h3 id="_2-데이터-검증" tabindex="-1">2. 데이터 검증 <a class="header-anchor" href="#_2-데이터-검증" aria-label="Permalink to &quot;2. 데이터 검증&quot;">​</a></h3><p>가져오기 전에 코알라 가계부가 자동으로 검증합니다.</p><ul><li>✅ 유효: 정상 가져오기 가능</li><li>⚠️ 무효: 형식 오류로 수정 필요</li><li>❌ 건너뛰기: 무효 항목을 제외하고 유효 항목만 가져오기 가능</li></ul><h3 id="_3-대량-데이터" tabindex="-1">3. 대량 데이터 <a class="header-anchor" href="#_3-대량-데이터" aria-label="Permalink to &quot;3. 대량 데이터&quot;">​</a></h3><ul><li>데이터가 많다면(예: 1000건 이상) 나눠서 가져오기를 권장합니다</li><li>가져오기 중에는 앱을 전면에 두어 주세요</li></ul><hr><h2 id="🔧-자주-묻는-질문" tabindex="-1">🔧 자주 묻는 질문 <a class="header-anchor" href="#🔧-자주-묻는-질문" aria-label="Permalink to &quot;🔧 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-파싱에-실패합니다" tabindex="-1">Q1: 파싱에 실패합니다. <a class="header-anchor" href="#q1-파싱에-실패합니다" aria-label="Permalink to &quot;Q1: 파싱에 실패합니다.&quot;">​</a></h3><p>아래를 확인해 주세요.</p><ol><li>파일 형식(CSV/Excel)이 올바른지</li><li>가져오기 소스 선택이 맞는지</li><li>파일이 손상되지 않았는지</li><li>인코딩(UTF-8 권장)</li></ol><h3 id="q2-가져온-데이터가-일부-누락됩니다" tabindex="-1">Q2: 가져온 데이터가 일부 누락됩니다. <a class="header-anchor" href="#q2-가져온-데이터가-일부-누락됩니다" aria-label="Permalink to &quot;Q2: 가져온 데이터가 일부 누락됩니다.&quot;">​</a></h3><p>가능한 원인:</p><ol><li>일부 행이 형식 오류로 건너뛰어짐</li><li>카테고리/계정이 없어 생성 또는 수정이 필요</li><li>미리보기 화면에서 무효 항목을 확인해 주세요</li></ol><h3 id="q3-이미지는-가져올-수-있나요" tabindex="-1">Q3: 이미지는 가져올 수 있나요? <a class="header-anchor" href="#q3-이미지는-가져올-수-있나요" aria-label="Permalink to &quot;Q3: 이미지는 가져올 수 있나요?&quot;">​</a></h3><p>현재는 지원하지 않습니다.</p><h3 id="q4-가져온-뒤-수정할-수-있나요" tabindex="-1">Q4: 가져온 뒤 수정할 수 있나요? <a class="header-anchor" href="#q4-가져온-뒤-수정할-수-있나요" aria-label="Permalink to &quot;Q4: 가져온 뒤 수정할 수 있나요?&quot;">​</a></h3><p>가능합니다. 가져온 후 내역 목록에서 수정/삭제할 수 있습니다.</p><h3 id="q5-여러-파일을-한-번에-가져올-수-있나요" tabindex="-1">Q5: 여러 파일을 한 번에 가져올 수 있나요? <a class="header-anchor" href="#q5-여러-파일을-한-번에-가져올-수-있나요" aria-label="Permalink to &quot;Q5: 여러 파일을 한 번에 가져올 수 있나요?&quot;">​</a></h3><p>현재는 지원하지 않습니다. 파일을 하나씩 가져와 주세요.</p><hr><h2 id="📚-관련-가이드" tabindex="-1">📚 관련 가이드 <a class="header-anchor" href="#📚-관련-가이드" aria-label="Permalink to &quot;📚 관련 가이드&quot;">​</a></h2><ul><li><a href="./02-wechat-bill-import-guide">WeChat 내역 가져오기</a></li><li><a href="./03-alipay-bill-import-guide">Alipay 내역 가져오기</a></li><li><a href="./04-multi-ledger-guide">멀티 장부</a></li></ul><hr><p><strong>마지막 업데이트</strong>: 2026년 1월</p>`,67)])])}const k=i(r,[["render",s]]);export{u as __pageData,k as default};
